from lib import *
S = SS('n37')
steps = [
    step("LoadHTMLGlob 的行为由模式决定:debug 模式下用 HTMLDebug,每次 Instance 都 loadTemplate 重新 ParseGlob(源码里 render/html.go 76–82 行是三种 template.Must(...ParseFiles / ParseGlob / ParseFS));release 模式下启动时解析一次,放进 HTMLProduction,每次渲染直接执行。", t=tl(S(1)), mark=lidx(S(1), 'HTMLDebug', 'ParseGlob(r.Glob)'), done=lidx(S(1), 'HTMLProduction', 'LoadHTMLGlob'), kv=KV([['debug', 'HTMLDebug:每次渲染重新解析模板'], ['release', 'HTMLProduction:启动时解析一次'], ['解析函数', 'template.Must,模板有错会直接 panic']], ['debug'])),
    step("基本用法:LoadHTMLGlob(\"tpl/*.html\"),模板名是文件的 base name(index.html、user.html);html/template 自动转义:正文里的 <b>、&、'、<script> 都被转成 &lt; &amp; &#39;,XSS 内容失效;传 template.HTML 类型的值才会原样输出(Bio 为 template.HTML 时输出 <em>…</em>,普通字符串则被转义);SetFuncMap 注册的 upper 函数在模板里可用(ANN、BOB);{{define}}/{{template}} 嵌套正常(layout + content)。Content-Type 是 text/html; charset=utf-8。", t=tl(S(2)), mark=lidx(S(2), '&lt;script&gt;', '可信的 HTML', '不可信'), done=lidx(S(2), 'ANN', 'BOB', '嵌套模板', 'text/html; charset=utf-8'), kv=KV([['自动转义', '< > & \' 都转义'], ['template.HTML', '标记为可信,原样输出'], ['SetFuncMap', '注册模板函数']], ['template.HTML'])),
    step("debug 与 release 的区别:release 模式下改了模板文件,不重启仍然是旧内容(<h1>T</h1><p>B</p>);debug 模式下改完立刻生效(<h1>改过的模板 T</h1>)。代价:渲染一次 index.html(glob 匹配 5 个模板文件,每次请求新建一个 httptest 记录器)release 中位 1.7 µs,debug 119.5 µs,约 70 倍。", t=tl(S(3)), mark=lidx(S(3), 'GIN_MODE=debug', '119.5'), done=lidx(S(3), 'GIN_MODE=release', '1.7 µs'), b=bars([['release:渲染一次', 1.7, '1.7 µs'], ['debug:渲染一次', 119.5, '119.5 µs']], 119.5, done=[0], mark=[1]), kv=KV([['release', '启动时解析,改文件要重启'], ['debug', '每次渲染都重新解析,热更新'], ['耗时', '1.7 µs vs 119.5 µs']], ['耗时'])),
    step("同名文件:LoadHTMLGlob(\"tpl/*/*.html\") 会解析 a/item.html 和 b/item.html,模板名只取 base name,两个都叫 item.html,渲染出来的是后一个(B 目录的 item);要避免冲突,在文件里用 {{define \"c/uniq.html\"}}…{{end}} 起带目录的名字——c.HTML(…, \"c/uniq.html\") 能渲染,而原来的 uniq.html 这个名字渲染出空串。", t=tl(S(4)), mark=lidx(S(4), '/a   ', '/uu'), done=lidx(S(4), '/u   '), kv=KV([['模板名', '文件的 base name,不含目录'], ['同名文件', '后一个覆盖前一个,没有任何提示'], ['解决', '用 {{define "目录/文件名"}} 起唯一的名字']], ['同名文件'])),
    step("出错:模板名不存在(nope.html)→ 状态 200、正文为空,c.Errors 里有 html/template: \"nope.html\" is undefined;渲染中途出错(partial.html 里引用了结构体没有的字段 Missing)→ 状态 200、客户端收到已经写出的 \"ok\" 半截内容,c.Errors 里有 can't evaluate field Missing in type struct { X int };SetFuncMap 写在 LoadHTMLGlob 之后:模板里的 upper 函数还没注册,LoadHTMLGlob 直接 panic(function \"upper\" not defined)。", t=tl(S(5)), mark=lidx(S(5), '/nope', '/partial', 'panic: template: user.html:1: function "upper" not defined'), done=lidx(S(5), 'c.Errors: html/template', 'c.Errors: template: partial.html'), kv=KV([['模板不存在', '200 + 空正文,错误在 c.Errors'], ['渲染中途出错', '已写出的半截内容仍发给客户端'], ['SetFuncMap 晚了', 'LoadHTMLGlob panic']], ['渲染中途出错'])),
]
A = mkartn('n37', 37, 'Gin,HTML模板,LoadHTMLGlob,html/template,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 HTML 模板:release 模式启动时解析一次,debug 模式每次渲染重新解析(1.7 µs 对 119.5 µs);自动转义与 template.HTML;不同目录下的同名文件互相覆盖;模板不存在时返回 200 加空正文,渲染中途出错会发出半截页面;SetFuncMap 要在 LoadHTMLGlob 之前。',
    'LoadHTMLGlob 什么时候解析模板?debug 与 release 差多少?放在子目录里的同名模板会怎样?出错的时候用户看到什么?这篇用真实的模板文件把 Gin 的 HTML 渲染一步步试出来。',
    [('1.7 vs 119.5 µs', 'release 与 debug 模式渲染一次的耗时(glob 匹配 5 个模板文件)'), ('后一个覆盖', 'a/item.html 与 b/item.html 同名时,渲染出的是 B 目录的那个'), ('200 + 空正文', '模板名不存在时的响应')],
    [('两种渲染器', '<p>debug 模式用 <code>HTMLDebug</code>:每次渲染都重新 <code>ParseGlob</code>,所以改模板立刻生效,开发很方便;release 模式用 <code>HTMLProduction</code>,启动时解析一次。这也是线上必须设置 <code>GIN_MODE=release</code> 的原因之一:debug 模式每次渲染多出上百微秒的解析开销,还会有文件 I/O。</p>'),
     ('自动转义', '<p>用的是标准库的 <code>html/template</code>,会按上下文自动转义(HTML 文本、属性、JS、URL 各不相同)。用户输入里的 <code>&lt;script&gt;</code> 会变成实体。只有明确标成 <code>template.HTML</code> 的值才原样输出,所以不要把用户输入转成这个类型。</p>'),
     ('模板名与冲突', '<p><code>ParseGlob</code> 用文件的 base name 做模板名,不含目录。<code>tpl/*/*.html</code> 下两个目录里的 <code>item.html</code> 会冲突,后一个静默覆盖前一个。要避免,在文件里用 <code>{{define "a/item.html"}}</code> 起带目录的唯一名字,再按这个名字渲染。</p>'),
     ('失败时的表现', '<p>模板名不存在、渲染中途出错,Gin 都只是 <code>c.Error</code> 并 <code>Abort</code>:前者客户端看到 200 加空页面,后者看到截断的页面(模板边执行边写出)。这些错误只在 <code>c.Errors</code> 里,要靠错误处理中间件或日志发现。想避免半截页面,可以自己先 <code>ExecuteTemplate</code> 到缓冲区,成功后再写出。</p>'),
     ('函数与时机', '<p><code>SetFuncMap</code> 必须在 <code>LoadHTMLGlob</code> 之前调用,否则模板里引用的函数在解析时还不存在,<code>LoadHTMLGlob</code> 直接 panic(这是启动期的错误,不会漏到线上)。</p>')],
    steps,
    [ENV_N_GIN + '。模板文件是实验时写在程序目录里的几个小文件;请求用 httptest 直接调用 ServeHTTP;耗时是 testing.Benchmark 的 5 轮中位数(每次迭代包含新建 httptest.NewRecorder);GIN_MODE 通过环境变量设置;其余每种情形各一次',
     '没有验证:模板嵌套在多级目录时 LoadHTMLFS / embed 的行为;{{block}} 与 {{template}} 的覆盖语义细节;自定义 Delims;热更新在 release 模式下的做法(如监听文件);大模板集合(几百个文件)的解析耗时;并发渲染的安全性(标准库文档保证模板可并发执行)'],
    'HTML 模板')
